package cn.seu.personalhub;

import android.app.*;
import android.app.job.*;
import android.content.*;
import android.net.Uri;
import android.os.*;
import android.view.*;
import android.webkit.*;
import android.widget.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import org.json.JSONObject;

public class MainActivity extends Activity{
  WebView web;HubBridge bridge;ValueCallback<Uri[]> files;ValueCallback<String> backup;String pendingBackup;boolean pageReady=false;
  static final String ORIGIN="https://appassets.androidplatform.net";
  @Override public void onCreate(Bundle saved){super.onCreate(saved);web=new WebView(this);bridge=new HubBridge(this,web,null);configure(web,bridge);web.setWebChromeClient(new WebChromeClient(){public boolean onJsAlert(WebView v,String url,String message,JsResult result){new AlertDialog.Builder(MainActivity.this).setMessage(message).setPositiveButton("确定",(d,w)->result.confirm()).setOnCancelListener(d->result.cancel()).show();return true;}public boolean onJsConfirm(WebView v,String url,String message,JsResult result){new AlertDialog.Builder(MainActivity.this).setMessage(message).setPositiveButton("确定",(d,w)->result.confirm()).setNegativeButton("取消",(d,w)->result.cancel()).setOnCancelListener(d->result.cancel()).show();return true;}public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> callback,FileChooserParams params){if(files!=null)files.onReceiveValue(null);files=callback;Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("application/json").addCategory(Intent.CATEGORY_OPENABLE);try{startActivityForResult(intent,7);}catch(Exception e){files.onReceiveValue(null);files=null;}return true;}});web.setDownloadListener((url,ua,cd,mime,size)->{if(url.equals(ORIGIN+"/api/backup"))exportBackup();else UriCheck.open(this,url);});web.setWebViewClient(new AssetClient(this){@Override public void onPageFinished(WebView view,String url){if(url.startsWith(ORIGIN+"/index.html"))pageReady=true;}@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){String url=r.getUrl().toString();if(url.equals(ORIGIN+"/api/backup")){exportBackup();return true;}if(url.startsWith(ORIGIN+"/"))return false;UriCheck.open(MainActivity.this,url);return true;}});setContentView(web);web.setOnApplyWindowInsetsListener((v,insets)->{if(Build.VERSION.SDK_INT>=30){android.graphics.Insets b=insets.getInsets(WindowInsets.Type.systemBars());v.setPadding(b.left,b.top,b.right,b.bottom);}else v.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets;});web.loadUrl(ORIGIN+"/index.html?v=105");SyncManager.schedule(this);}
  static void configure(WebView web,HubBridge bridge){WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setCacheMode(WebSettings.LOAD_NO_CACHE);s.setAllowFileAccess(false);s.setAllowContentAccess(true);s.setJavaScriptCanOpenWindowsAutomatically(false);s.setSupportMultipleWindows(false);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);web.addJavascriptInterface(bridge,"AndroidHub");}
  void exportBackup(){web.evaluateJavascript("window.__exportNativeBackup()",value->{try{pendingBackup=new org.json.JSONTokener(value).nextValue().toString();Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("application/json").putExtra(Intent.EXTRA_TITLE,"东南消息站备份.json");startActivityForResult(i,8);}catch(Exception e){Toast.makeText(this,"备份导出失败，请重试",Toast.LENGTH_SHORT).show();}});}
  @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req==7&&files!=null){files.onReceiveValue(result==RESULT_OK&&data!=null?new Uri[]{data.getData()}:null);files=null;}if(req==8&&result==RESULT_OK&&data!=null&&pendingBackup!=null){try(OutputStream out=getContentResolver().openOutputStream(data.getData())){out.write(pendingBackup.getBytes(StandardCharsets.UTF_8));Toast.makeText(this,"备份已保存",Toast.LENGTH_SHORT).show();}catch(Exception e){Toast.makeText(this,"备份未能保存",Toast.LENGTH_SHORT).show();}pendingBackup=null;}}
  @Override public void onResume(){super.onResume();if(Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,()->handleBack());if(pageReady){SyncManager.start(this,"","resume",null);web.evaluateJavascript("window.dispatchEvent(new Event('hub-resumed'))",null);}}
  void handleBack(){web.evaluateJavascript("typeof window.__nativeBack==='function'?window.__nativeBack():false",value->{if("false".equals(value))finish();});}
  @Override public void onBackPressed(){handleBack();}
  @Override protected void onDestroy(){if(bridge!=null)bridge.close();if(web!=null){web.removeJavascriptInterface("AndroidHub");web.destroy();}super.onDestroy();}
  static class AssetClient extends WebViewClient{final Context context;AssetClient(Context c){context=c;}@Override public WebResourceResponse shouldInterceptRequest(WebView view,WebResourceRequest req){Uri uri=req.getUrl();if(!"appassets.androidplatform.net".equals(uri.getHost()))return null;String p=uri.getPath();if("/".equals(p))p="/index.html";if(p.contains(".."))return new WebResourceResponse("text/plain","UTF-8",new ByteArrayInputStream(new byte[0]));try{String mime=p.endsWith(".js")?"text/javascript":p.endsWith(".css")?"text/css":p.endsWith(".svg")?"image/svg+xml":p.endsWith(".json")?"application/json":"text/html";java.util.Map<String,String> headers=new java.util.HashMap<>();headers.put("Cache-Control","no-store");headers.put("Content-Security-Policy","default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self' data: https:; connect-src 'self'; object-src 'none'; frame-src 'none'; base-uri 'none'");return new WebResourceResponse(mime,"UTF-8",200,"OK",headers,context.getAssets().open("public"+p));}catch(Exception e){return new WebResourceResponse("text/plain","UTF-8",404,"Not Found",null,new ByteArrayInputStream(new byte[0]));}}}
}
